var age = Math.max(0, +v('age') || 0), life = Math.max(1, +v('life') || 85);
var left = Math.round(Math.max(0, life - age) * 52), genki = Math.round(Math.max(0, Math.min(75, life) - age) * 52);
var total = Math.max(1, Math.round(Math.max(life, age) * 52));
left = Math.min(total, left);
Crowd.units(el, { total: total, used: total - left, unit: '回',
title: '一生の週末を玉で並べると',
final: function (l) { return 'のこり ' + l.toLocaleString('ja-JP') + '回。そのうち元気に動ける（75歳まで）のは ' + genki.toLocaleString('ja-JP') + '回です。'; } });
